j:jelly.g:evaluate:
var today = new GlideChoice("today", gs.getMessage("Today"));
var tomorrow = new GlideChoice("tomorrow", gs.getMessage("Tomorrow"));
var thisWeek = new GlideChoice("this_week", gs.getMessage("This week"));
var nextWeek = new GlideChoice("next_week", gs.getMessage("Next week"));
var thisMonth = new GlideChoice("this_month", gs.getMessage("This month"));
var nextMonth = new GlideChoice("next_month", gs.getMessage("Next month"));
var thisQuarter = new GlideChoice("this_quarter", gs.getMessage("This quarter"));
var nextQuarter = new GlideChoice("next_quarter", gs.getMessage("Next quarter"));
var dateRange = new GlideChoice("date_range", gs.getMessage("Date range"));

var choices = new GlideChoiceList();
choices.add(today);
choices.add(tomorrow);
choices.add(thisWeek);
choices.add(nextWeek);
choices.add(thisMonth);
choices.add(nextMonth);
choices.add(thisQuarter);
choices.add(nextQuarter);
choices.add(dateRange);
choices;
